('', 'start', '{"param": {}, "fildariane": {"span": "Fil d''ariane"}, "left": {"hgroup": ["MATIERES", "COMPETENCES", "TOPICS"]}, "menus": {"div": {"title": "S''inscrire, se connecter, ou encore soumettre votre ressource d''enseignement", "sousmenu": [{"lien": {"html": "Devenir membre/s''enregistrer", "href": "creer-compte-utilisateur", "title": "Devenir membre en ouvrant un compte utilisateur became.net"}}, {"lien": {"html": "Se connecter", "href": "se-connecter", "title": "Se connecter à son compte utilisateur"}}, {"lien": {"html": "Ajouter des données", "href": "#!ajouter-donnees", "title": "Alimenter le réseau social en ressources d''enseignement", "ul": [{"lien": {"data-data": "courses", "html": "AJOUTER UN COURS (niveau>filière>matière>sujet>cours)", "href": "#!ajouter-cours-enseignement", "title": "Programmer un cours d''enseignement"}}, {"lien": {"data-data": "ressources", "html": "AJOUTER UNE RESSOURCE", "href": "#!ajouter-ressource-educative", "title": "Alimenter le réseau social d''une ressource d''enseignement (cela peut être n''importe quoi (le scan d''un devoir, une fiche de révision, un ensemble de données, un fichier audio...)"}}, {"lien": {"data-data": "classes", "html": "OUVRIR UNE CLASSE", "href": "#!creer-classe-enseignement", "title": "Créer une nouvelle classe pour une filiere (6ème, 1ere Scientifique, IUT Compta, Webmaster, Cuisine Japonaise..."}}, {"lien": {"data-data": "profs", "html": "SOUMETTRE UN PROFIL PROFESSEUR", "href": "#!creer-profession-enseignement", "title": "Créer un nouveau profil de professeur pour pouvoir enseigner une matiere et ses différents sujets aux apprenants de became.net"}}, {"lien": {"data-data": "niveaux", "html": "OUVRIR UN NOUVEAU NIVEAU", "href": "#!creer-niveau-enseignement", "title": "Became.net n''est pas capable de référencer tout ce qui existe en terme d''enseignement dans les pays du monde entier, veuillez nous aider en créant un niveau d''enseignement si celui-ci n''a pas encore été ajouter par un autre utilisateur"}}, {"lien": {"data-data": "filieres", "html": "OUVRIR UNE NOUVELLE FILIERE", "href": "#!creer-filiere-enseignement", "title": "Créer une nouvelle filières dans un des 4 différents niveaux (scolaire, universitaire, professionnel, ou passion)"}}, {"lien": {"data-data": "matieres", "html": "OUVRIR UNE NOUVELLE MATIERE", "href": "#!creer-matiere-enseignement", "title": "Vous êtes à l''université par exemple, en IUT Comptabilité, et une matière que vous recherché n''existe ni de près ni de loin dans nos données ??? Créer cette matière pour que les autres membres de became.net puisse l''alimenter en ressources ou trouver des cours d''enseignement"}}, {"lien": {"data-data": "sujets", "html": "OUVRIR UN NOUVEAU SUJET", "href": "#!creer-sujet-enseignement", "title": "Créer un nouveau sujet car celui-ci manque à l''appel dans les proposition de became.net"}}]}}]}}}', '{"param": {}, "fildariane": {"span": "Fil d''ariane"}, "left": {"hgroup": ["MATIERES", "COMPETENCES", "TOPICS"]}, "menus": {"div": {"title": "S''inscrire, se connecter, ou encore soumettre votre ressource d''enseignement", "sousmenu": [{"lien": {"html": "Devenir membre/s''enregistrer", "href": "creer-compte-utilisateur", "title": "Devenir membre en ouvrant un compte utilisateur became.net"}}, {"lien": {"html": "Se connecter", "href": "se-connecter", "title": "Se connecter à son compte utilisateur"}}, {"lien": {"html": "Ajouter des données", "href": "#!ajouter-donnees", "title": "Alimenter le réseau social en ressources d''enseignement", "ul": [{"lien": {"data-data": "courses", "html": "AJOUTER UN COURS (niveau>filière>matière>sujet>cours)", "href": "#!ajouter-cours-enseignement", "title": "Programmer un cours d''enseignement"}}, {"lien": {"data-data": "ressources", "html": "AJOUTER UNE RESSOURCE", "href": "#!ajouter-ressource-educative", "title": "Alimenter le réseau social d''une ressource d''enseignement (cela peut être n''importe quoi (le scan d''un devoir, une fiche de révision, un ensemble de don